SET age = #{age}, gender = #{gender}, travel_companions = #{travelCompanions},
    cold_sensitivity = #{coldSensitivity}, heat_sensitivity = #{heatSensitivity},
    health_issues = #{healthIssues}, packing_style = #{packingStyle},
    updated_time = #{updatedTime}
